/**
 * Migration 1: the baseline.
 *
 * Everything the app did to its database before migrations were versioned: the
 * schema as it stood then (frozen here, so this migration never changes), the
 * columns added since the first release, and the one-time data conversions. Every
 * step is idempotent, so it is also safe on a database that predates versioning
 * and already has all of this (version 0 with data).
 *
 * Do not edit this file. Put new changes in a new migration.
 */

import type Database from 'better-sqlite3';
import { parseLegacyRubric } from '../../scoring/scoring-config.js';
import { addColumnIfMissing, type Migration } from '../migrator.js';

const BASELINE_SCHEMA_SQL = `
-- SQLite Database Schema for Hiring Helper

-- Application states table: Stores possible application statuses from BambooHR
CREATE TABLE IF NOT EXISTS application_states (
  id INTEGER PRIMARY KEY,
  status TEXT NOT NULL UNIQUE,
  active INTEGER NOT NULL DEFAULT 1
);

-- Jobs table: Stores job postings
CREATE TABLE IF NOT EXISTS jobs (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  posted_date TEXT,
  status TEXT,
  posting_url TEXT,
  description TEXT,
  -- Legacy hand-written per-job rubric. Superseded by scoring_config; kept as a
  -- backup, and still used only when it could not be converted (see
  -- parseLegacyRubric). NULL means no hand-written rubric.
  system_prompt TEXT,
  -- Structured per-job scoring criteria (JSON ScoringConfig: weighted evaluation
  -- areas + which red flags are on). NULL means use the default criteria.
  scoring_config TEXT,
  -- When a person confirmed this job's scoring criteria (NULL = not yet). Scoring is
  -- blocked until it is set and the posting text exists. See scoring/job-readiness.ts.
  criteria_confirmed_at TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);

-- Applicants table: Stores candidate information
CREATE TABLE IF NOT EXISTS applicants (
  id INTEGER PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT NOT NULL,
  source TEXT,
  phone_number TEXT,
  address_line1 TEXT,
  address_line2 TEXT,
  city TEXT,
  state TEXT,
  zipcode TEXT,
  country TEXT,
  linkedin_url TEXT,
  available_start_date TEXT,
  education TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);

-- Applications table: Links applicants to jobs
CREATE TABLE IF NOT EXISTS applications (
  id INTEGER PRIMARY KEY,
  applied_date TEXT NOT NULL,
  status_id INTEGER,
  -- The status BambooHR last reported for this application (set by sync). The
  -- working status_id can diverge from this via local triage; a row where
  -- status_id <> bamboo_status_id is a change pending push back to BambooHR.
  bamboo_status_id INTEGER,
  rating INTEGER,
  applicant_id INTEGER NOT NULL,
  job_id INTEGER NOT NULL,
  resume_file_id INTEGER,
  cover_letter_file_id INTEGER,
  referred_by TEXT,
  -- Selected BambooHR application answers, captured on sync for display/triage:
  -- the candidate's desired pay and their answer to the commuting-distance question.
  desired_salary TEXT,
  commuting_answer TEXT,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (applicant_id) REFERENCES applicants(id) ON DELETE CASCADE,
  FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE,
  FOREIGN KEY (status_id) REFERENCES application_states(id) ON DELETE SET NULL
);

-- Application scores table: Stores AI-generated confidence scores
CREATE TABLE IF NOT EXISTS application_scores (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  application_id INTEGER NOT NULL UNIQUE,
  score INTEGER NOT NULL CHECK(score >= 0 AND score <= 100),
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (application_id) REFERENCES applications(id) ON DELETE CASCADE
);

-- Application flags table: structured reasons attached to an application
-- (e.g. location / name skips, or studying / no_exp content flags).
CREATE TABLE IF NOT EXISTS application_flags (
  application_id INTEGER NOT NULL,
  flag TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now')),
  PRIMARY KEY (application_id, flag),
  FOREIGN KEY (application_id) REFERENCES applications(id) ON DELETE CASCADE
);

-- Content updates table: Tracks when data was last synced from BambooHR
CREATE TABLE IF NOT EXISTS content_updates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  timestamp TEXT DEFAULT (datetime('now')),
  sync_type TEXT DEFAULT 'full',
  applications_synced INTEGER DEFAULT 0,
  notes TEXT
);

-- Create indexes for common queries
CREATE INDEX IF NOT EXISTS idx_applications_applicant_id ON applications(applicant_id);
CREATE INDEX IF NOT EXISTS idx_applications_job_id ON applications(job_id);
CREATE INDEX IF NOT EXISTS idx_applications_status_id ON applications(status_id);
CREATE INDEX IF NOT EXISTS idx_applications_applied_date ON applications(applied_date);
CREATE INDEX IF NOT EXISTS idx_applicants_email ON applicants(email);
CREATE INDEX IF NOT EXISTS idx_application_scores_application_id ON application_scores(application_id);
CREATE INDEX IF NOT EXISTS idx_content_updates_timestamp ON content_updates(timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_application_states_status ON application_states(status);
CREATE INDEX IF NOT EXISTS idx_application_flags_application_id ON application_flags(application_id);
CREATE INDEX IF NOT EXISTS idx_application_flags_flag ON application_flags(flag);
`;

/**
 * Convert hand-written per-job rubrics into structured scoring criteria, once.
 * The original text stays in `system_prompt` as a backup; a rubric that cannot
 * be converted faithfully is left alone and keeps being used as written.
 */
function convertLegacyRubrics(db: Database.Database): void {
  const candidates = db
    .prepare<[], { id: number; system_prompt: string }>(
      `SELECT id, system_prompt FROM jobs
       WHERE scoring_config IS NULL AND system_prompt IS NOT NULL AND TRIM(system_prompt) <> ''`
    )
    .all();
  const update = db.prepare('UPDATE jobs SET scoring_config = ? WHERE id = ?');

  for (const job of candidates) {
    const config = parseLegacyRubric(job.system_prompt);
    if (config) {
      update.run(JSON.stringify(config), job.id);
      console.info(`🛠️  Migration: converted job ${job.id}'s scoring rubric to structured criteria`);
    } else {
      console.warn(
        `⚠️  Job ${job.id} has a hand-written scoring rubric that could not be converted; it will keep being used as written.`
      );
    }
  }
}

/**
 * Jobs that were already being used before criteria confirmation existed (they
 * have customized criteria, or applicants that have been scored) count as
 * confirmed, so introducing the "set up before scoring" step never blocks work
 * that is already under way. Genuinely new jobs have neither, so they stay
 * unconfirmed until a person confirms them.
 */
function confirmCriteriaOfJobsInUse(db: Database.Database): void {
  const result = db
    .prepare(
      `UPDATE jobs SET criteria_confirmed_at = datetime('now')
       WHERE criteria_confirmed_at IS NULL
         AND (scoring_config IS NOT NULL
              OR EXISTS (SELECT 1 FROM applications a
                         INNER JOIN application_scores s ON s.application_id = a.id
                         WHERE a.job_id = jobs.id))`
    )
    .run();
  if (result.changes > 0) {
    console.info(`🛠️  Migration: marked ${result.changes} job(s) already in use as having confirmed criteria`);
  }
}

export const baselineMigration: Migration = {
  version: 1,
  name: 'baseline schema',
  up(db) {
    db.exec(BASELINE_SCHEMA_SQL);

    // Columns added after the first release, for databases created before them.
    addColumnIfMissing(db, 'jobs', 'description', 'TEXT');
    addColumnIfMissing(db, 'jobs', 'system_prompt', 'TEXT');
    addColumnIfMissing(db, 'jobs', 'scoring_config', 'TEXT');
    convertLegacyRubrics(db);
    addColumnIfMissing(db, 'jobs', 'criteria_confirmed_at', 'TEXT');
    confirmCriteriaOfJobsInUse(db);
    addColumnIfMissing(db, 'applications', 'desired_salary', 'TEXT');
    addColumnIfMissing(db, 'applications', 'commuting_answer', 'TEXT');
    addColumnIfMissing(db, 'applications', 'bamboo_status_id', 'INTEGER');
  },
};
